    <script>
        document.addEventListener("DOMContentLoaded", function() {
            const NOTICE = <?= site_json(cfg("notice")) ?>;
            const STORAGE_KEY = "lover_site_notice_" + NOTICE;

            // 检查是否已显示过
            if (NOTICE && !localStorage.getItem(STORAGE_KEY)) {
                document.getElementById('update-modal-overlay').style.display = 'flex';
            }

            // 点击确认按钮
            document.getElementById('confirm-update-btn').addEventListener('click', function() {
                document.getElementById('update-modal-overlay').style.display = 'none';
                localStorage.setItem(STORAGE_KEY, 'true');
            });
        });
    </script>

    
    
    
    
    
    
    
    
    
    
