    <script>
    // ===== 全局歌单播放器 =====
    var PLAYLIST = <?= site_json(site_playlist()) ?>;

    var _plAudio = new Audio();
    _plAudio.preload = 'none';
    var _plResumeTime = 0;
    _plAudio.volume = 0.6;
    var _plIndex = -1;
    var _plPlaying = false;
    var _plLyricLines = [];  // [{time:秒, text:'歌词行'}]

    // ===== 跨页面播放状态持久化 =====
    function _plSaveState() {
        try {
            var state = {
                index: _plIndex,
                playing: _plPlaying,
                currentTime: _plResumeTime || _plAudio.currentTime || 0,
                volume: _plAudio.volume
            };
            localStorage.setItem('_plState', JSON.stringify(state));
        } catch(e) {}
    }

    function _plRestoreState() {
        try {
            var raw = localStorage.getItem('_plState');
            if (!raw) return false;
            var state = JSON.parse(raw);
            if (state.index >= 0 && state.index < PLAYLIST.length) {
                _plIndex = state.index;
                _plAudio.volume = typeof state.volume === 'number' && state.volume >= 0 && state.volume <= 1 ? state.volume : 0.6;
                _plLyricLines = _plParseLRC(PLAYLIST[_plIndex].lyrics || '');
                _plResumeTime = Math.max(0, Number(state.currentTime) || 0);
                if (state.playing) {
                    _plPlaying = true;
                    _plPlay();
                }
                _plUpdateUI();
                return true;
            }
        } catch(e) {}
        return false;
    }

    // 定时保存播放进度
    setInterval(_plSaveState, 3000);

    // 页面卸载时保存
    window.addEventListener('beforeunload', _plSaveState);

    // ===== LRC 歌词解析 =====
    function _plParseLRC(lrc) {
        if (!lrc) return [];
        var lines = lrc.split('\n');
        var result = [];
        var timeReg = /\[(\d{1,2}):(\d{1,2})(?:[.:]\d{1,3})?\]/g;
        for (var i = 0; i < lines.length; i++) {
            var txt = lines[i].replace(/\[.*?\]/g, '').trim();
            if (!txt) continue;
            var times = [];
            var m;
            timeReg.lastIndex = 0;
            while ((m = timeReg.exec(lines[i])) !== null) {
                times.push(parseInt(m[1]) * 60 + parseInt(m[2]));
            }
            for (var j = 0; j < times.length; j++) {
                result.push({ time: times[j], text: txt });
            }
        }
        result.sort(function(a, b) { return a.time - b.time; });
        return result;
    }

    function _plUpdateLyric() {
        var el = document.getElementById('headerLyric');
        if (!el || _plLyricLines.length === 0) return;
        var ct = _plAudio.currentTime;
        var text = '';
        for (var i = _plLyricLines.length - 1; i >= 0; i--) {
            if (ct >= _plLyricLines[i].time) {
                text = _plLyricLines[i].text;
                break;
            }
        }
        if (el.textContent !== text) el.textContent = text;
    }

    function _plFormatTime(sec) {
        if (isNaN(sec) || sec < 0) return '0:00';
        var m = Math.floor(sec / 60);
        var s = Math.floor(sec % 60);
        return m + ':' + (s < 10 ? '0' : '') + s;
    }

    function _plUpdateUI() {
        var cover = document.getElementById('plCover');
        var name = document.getElementById('plName');
        var artist = document.getElementById('plArtist');
        var playBtn = document.getElementById('plPlayBtn');
        var list = document.getElementById('plList');
        // 显示当前歌曲信息，无选中则默认显示第一首
        var displayIdx = _plIndex >= 0 ? _plIndex : (PLAYLIST.length > 0 ? 0 : -1);
        if (displayIdx >= 0) {
            var song = PLAYLIST[displayIdx];
            if (cover) cover.src = song.cover;
            if (name) name.textContent = song.name;
            if (artist) artist.textContent = song.artist;
        }
        if (playBtn) {
            playBtn.innerHTML = _plPlaying
                ? '<svg class="iconfont icon-zanting" aria-hidden="true"><use href="#icon-zanting" xlink:href="#icon-zanting"></use></svg>'
                : '<svg class="iconfont icon-bofang" aria-hidden="true"><use href="#icon-bofang" xlink:href="#icon-bofang"></use></svg>';
        }
        // 更新歌单列表高亮
        if (list) {
            list.querySelectorAll('.pl-song').forEach(function(el, idx) {
                el.classList.toggle('active', idx === _plIndex);
                var icon = el.querySelector('.pl-song-idx');
                if (icon) {
                    icon.innerHTML = (idx === _plIndex && _plPlaying)
                        ? '<span class="pl-playing-icon">♫</span>'
                        : (idx + 1);
                }
            });
        }
        // 更新手机端音乐按钮状态
        var mobileBtn = document.getElementById('mobileMusicBtn');
        if (mobileBtn) {
            mobileBtn.classList.toggle('playing', _plPlaying);
        }
        // 更新标题栏歌词区
        var center = document.querySelector('.header-bar-center');
        if (center) center.classList.toggle('playing', _plPlaying);

        // 同步首页"我们的歌"卡片
        _plSyncIndexCard();
    }

    // 同步首页音乐卡片
    function _plSyncIndexCard() {
        var idxCoverImg = document.getElementById('musicCoverImg');
        var idxName = document.getElementById('musicName');
        var idxArtist = document.getElementById('musicArtist');
        var idxDisc = document.getElementById('musicDisc');
        var idxPlayBtn = document.getElementById('musicPlay');
        var displayIdx = _plIndex >= 0 ? _plIndex : (PLAYLIST.length > 0 ? 0 : -1);
        if (displayIdx >= 0) {
            var song = PLAYLIST[displayIdx];
            if (idxCoverImg) idxCoverImg.src = song.cover;
            if (idxName) idxName.textContent = song.name;
            if (idxArtist) idxArtist.textContent = song.artist;
        }
        if (idxDisc) {
            if (_plPlaying) idxDisc.classList.add('playing');
            else idxDisc.classList.remove('playing');
        }
        if (idxPlayBtn) {
            idxPlayBtn.innerHTML = _plPlaying
                ? '<svg class="iconfont icon-zanting" aria-hidden="true"><use href="#icon-zanting" xlink:href="#icon-zanting"></use></svg>'
                : '<svg class="iconfont icon-bofang" aria-hidden="true"><use href="#icon-bofang" xlink:href="#icon-bofang"></use></svg>';
        }
    }

    function _plLoad(idx) {
        if (!Number.isInteger(idx) || idx < 0 || idx >= PLAYLIST.length) return;
        _plIndex = idx;
        _plResumeTime = 0;
        _plAudio.src = PLAYLIST[idx].src;
        _plLyricLines = _plParseLRC(PLAYLIST[idx].lyrics || '');
        _plUpdateUI();
    }

    function _plPlay() {
        if (PLAYLIST.length === 0) return;
        if (_plIndex < 0) _plLoad(0);
        if (!_plAudio.getAttribute('src')) _plAudio.src = PLAYLIST[_plIndex].src;
        if (_plResumeTime) {
            if (_plAudio.readyState >= 1) {
                _plAudio.currentTime = _plResumeTime;
                _plResumeTime = 0;
            } else if (!_plAudio._resumePending) {
                _plAudio._resumePending = true;
                _plAudio.addEventListener('loadedmetadata', function() {
                    if (_plResumeTime) _plAudio.currentTime = _plResumeTime;
                    _plResumeTime = 0;
                    _plAudio._resumePending = false;
                }, { once: true });
            }
        }
        _plPlaying = true;
        _plUpdateUI();
        _plAudio.play().catch(function() {
            _plPlaying = false;
            _plUpdateUI();
        });
        _plSaveState();
    }

    function _plPause() {
        _plAudio.pause();
        _plPlaying = false;
        _plUpdateUI();
        _plSaveState();
        var el = document.getElementById('headerLyric');
        if (el) el.textContent = '';
    }

    function _plToggle() {
        if (_plPlaying) _plPause(); else _plPlay();
    }

    function _plNext() {
        if (PLAYLIST.length === 0) return;
        _plIndex = (_plIndex + 1) % PLAYLIST.length;
        _plLoad(_plIndex);
        if (_plPlaying || _plIndex >= 0) _plPlay();
        _plSaveState();
    }

    function _plPrev() {
        if (PLAYLIST.length === 0) return;
        _plIndex = (_plIndex - 1 + PLAYLIST.length) % PLAYLIST.length;
        _plLoad(_plIndex);
        if (_plPlaying || _plIndex >= 0) _plPlay();
        _plSaveState();
    }

    function _plPlaySong(idx) {
        _plLoad(idx);
        _plPlay();
        _plSaveState();
    }

    // 进度条和时间更新
    _plAudio.addEventListener('timeupdate', function() {
        var fill = document.getElementById('plProgressFill');
        var cur = document.getElementById('plCurrent');
        var dur = document.getElementById('plDuration');
        if (_plAudio.duration) {
            if (fill) fill.style.width = (_plAudio.currentTime / _plAudio.duration * 100).toFixed(1) + '%';
            if (cur) cur.textContent = _plFormatTime(_plAudio.currentTime);
            if (dur) dur.textContent = _plFormatTime(_plAudio.duration);
        }
        // 同步首页音乐卡片进度
        var idxFill = document.getElementById('musicProgressFill');
        var idxCur = document.getElementById('musicCurrent');
        var idxDur = document.getElementById('musicDuration');
        if (_plAudio.duration) {
            if (idxFill) idxFill.style.width = (_plAudio.currentTime / _plAudio.duration * 100).toFixed(1) + '%';
            if (idxCur) idxCur.textContent = _plFormatTime(_plAudio.currentTime);
            if (idxDur) idxDur.textContent = _plFormatTime(_plAudio.duration);
        }
        _plUpdateLyric();
    });

    _plAudio.addEventListener('ended', function() {
        _plNext();
    });

    // 进度条点击跳转
    (function(){
        var bar = document.getElementById('plProgressBar');
        if (bar) {
            bar.addEventListener('click', function(e) {
                if (!_plAudio.duration) return;
                var rect = bar.getBoundingClientRect();
                var pct = (e.clientX - rect.left) / rect.width;
                _plAudio.currentTime = pct * _plAudio.duration;
            });
        }
    })();

    // ===== 页面加载时恢复播放状态 =====
    _plRestoreState();

    // ===== 歌单弹窗 =====
    function openPlaylist() {
        var overlay = document.getElementById('plOverlay');
        var card = document.getElementById('plCard');
        if (overlay) overlay.classList.add('active');
        if (card) card.classList.add('active');
        document.body.style.overflow = 'hidden';
        // 无选中歌曲时默认显示第一首信息（不自动播放）
        _plUpdateUI();
    }

    function closePlaylist() {
        var overlay = document.getElementById('plOverlay');
        var card = document.getElementById('plCard');
        if (overlay) overlay.classList.remove('active');
        if (card) card.classList.remove('active');
        document.body.style.overflow = '';
    }

    // 暴露到全局
    window.openPlaylist = openPlaylist;
    window.closePlaylist = closePlaylist;
    window._plPlaySong = _plPlaySong;
    window._plToggle = _plToggle;
    window._plNext = _plNext;
    window._plPrev = _plPrev;
    window._plPlaying = function() { return _plPlaying; };
    window.PLAYLIST = PLAYLIST;

    // ===== 手机端音乐：点击弹出歌单列表 =====
    function toggleMobileMusic() {
        if (PLAYLIST.length === 0) return;
        // 点击音乐按钮 → 打开歌单悬浮卡片
        var card = document.getElementById('plCard');
        if (card && card.classList.contains('active')) {
            closePlaylist();
        } else {
            openPlaylist();
        }
    }

    // 手机端底部导航栏 - 极光胶囊初始定位（仅首次 + resize）
    // active 状态与 PJAX 胶囊位置统一由 footer.php 的 handlePageSwitch / updateMobileNavCapsule 管理
    (function(){
        function initAuroraCapsule(){
            var nav = document.getElementById('mobileBottomNav');
            if(!nav) return;
            var capsule = document.getElementById('auroraCapsule');
            if(!capsule) return;

            function moveCapsule(){
                var activeItem = nav.querySelector('.mobile-nav-item.active');
                if(!activeItem) return;
                var navRect = nav.getBoundingClientRect();
                var itemRect = activeItem.getBoundingClientRect();
                capsule.style.left = (itemRect.left - navRect.left) + 'px';
                capsule.style.width = itemRect.width + 'px';
            }

            // 首次渲染时定位（PHP 端已标 active 类）
            moveCapsule();

            // 窗口大小变化时重新计算
            window.addEventListener('resize', moveCapsule);
        }

        if(document.readyState === 'loading'){
            document.addEventListener('DOMContentLoaded', initAuroraCapsule);
        }else{
            initAuroraCapsule();
        }
    })();
    </script>

