    <script>
    // ===== 用户菜单交互（保留，与head.js中功能相同，但此处确保始终可用） =====

    // ===== 悬浮登录/注册卡片 =====
    var _authMode = 'login';

    function showAuthCard(mode) {
        _authMode = mode || 'login';
        var card = document.getElementById('authCard');
        var overlay = document.getElementById('authOverlay');
        document.getElementById('headerUser').classList.remove('open');

        applyAuthMode();

        overlay.classList.add('active');
        card.classList.add('active');
        document.body.style.overflow = 'hidden';

        // 聚焦第一个输入框
        setTimeout(function() {
            var form = _authMode === 'login' ? 'authLoginForm' : 'authRegisterForm';
            var firstInput = document.getElementById(form).querySelector('input');
            if (firstInput) firstInput.focus();
        }, 350);
    }

    function closeAuthCard() {
        var card = document.getElementById('authCard');
        var overlay = document.getElementById('authOverlay');
        card.classList.remove('active');
        overlay.classList.remove('active');
        document.body.style.overflow = '';
        // 清除错误/成功提示
        document.getElementById('authError').style.display = 'none';
        document.getElementById('authSuccess').style.display = 'none';
    }

    function switchAuthMode() {
        _authMode = _authMode === 'login' ? 'register' : 'login';
        applyAuthMode();
    }

    function applyAuthMode() {
        var loginForm = document.getElementById('authLoginForm');
        var regForm = document.getElementById('authRegisterForm');
        var title = document.getElementById('authTitle');
        var subtitle = document.getElementById('authSubtitle');
        var switchText = document.getElementById('authSwitchText');
        var switchLink = document.getElementById('authSwitchLink');

        document.getElementById('authError').style.display = 'none';
        document.getElementById('authSuccess').style.display = 'none';

        if (_authMode === 'login') {
            loginForm.style.display = '';
            regForm.style.display = 'none';
            title.textContent = '欢迎回来';
            subtitle.textContent = '登录你的账号';
            switchText.textContent = '还没有账号？';
            switchLink.textContent = '立即注册';
        } else {
            loginForm.style.display = 'none';
            regForm.style.display = '';
            title.textContent = '创建新账号';
            subtitle.textContent = '注册一个账号吧';
            switchText.textContent = '已有账号？';
            switchLink.textContent = '返回登录';
        }
    }

    function showAuthError(msg) {
        var el = document.getElementById('authError');
        el.innerHTML = '<svg class="iconfont icon-jinggao"><use href="#icon-jinggao" xlink:href="#icon-jinggao"></use></svg><span>' + msg + '</span>';
        el.style.display = 'flex';
        document.getElementById('authSuccess').style.display = 'none';
    }

    function showAuthSuccess(msg) {
        var el = document.getElementById('authSuccess');
        el.innerHTML = '<svg class="iconfont icon-chenggong"><use href="#icon-chenggong" xlink:href="#icon-chenggong"></use></svg><span>' + msg + '</span>';
        el.style.display = 'flex';
        document.getElementById('authError').style.display = 'none';
    }

    function refreshCaptcha(imgId) {
        var img = document.getElementById(imgId);
        if (!img) return;
        var type = imgId.indexOf('reg') === 0 ? 'register' : 'login';
        img.src = 'captcha.php?type=' + type + '&t=' + Date.now();
    }

    function showLoginCaptcha() {
        var f = document.getElementById('loginCaptchaField');
        if (f) f.style.display = '';
        refreshCaptcha('loginCaptchaImg');
    }

    function handleLogin(e) {
        e.preventDefault();
        var form = document.getElementById('authLoginForm');
        var data = new FormData(form);
        data.append('action', 'login');

        var btn = document.getElementById('authLoginBtn');
        btn.disabled = true;
        btn.textContent = '登录中...';

        fetch('api/user_api.php', { method: 'POST', body: data })
            .then(function(r) { return r.json(); })
            .then(function(res) {
                btn.disabled = false;
                btn.textContent = '登 录';
                if (res.code === 0) {
                    showAuthSuccess('登录成功！');
                    setTimeout(function() { location.reload(); }, 800);
                } else {
                    if (res.require_captcha || (res.data && res.data.require_captcha)) {
                        showLoginCaptcha();
                    } else if (document.getElementById('loginCaptchaField').style.display !== 'none') {
                        refreshCaptcha('loginCaptchaImg');
                        var lc = document.getElementById('loginCaptcha'); if (lc) lc.value = '';
                    }
                    showAuthError(res.msg || '登录失败');
                }
            })
            .catch(function() {
                btn.disabled = false;
                btn.textContent = '登 录';
                showAuthError('网络错误，请重试');
            });
        return false;
    }

    function handleRegister(e) {
        e.preventDefault();
        var form = document.getElementById('authRegisterForm');
        var data = new FormData(form);
        data.append('action', 'register');

        var btn = form.querySelector('.auth-submit');
        btn.disabled = true;
        btn.textContent = '注册中...';

        fetch('api/user_api.php', { method: 'POST', body: data })
            .then(function(r) { return r.json(); })
            .then(function(res) {
                btn.disabled = false;
                btn.textContent = '注 册';
                if (res.code === 0) {
                    showAuthSuccess('注册成功！');
                    setTimeout(function() { location.reload(); }, 800);
                } else {
                    refreshCaptcha('regCaptchaImg');
                    var rc = document.getElementById('regCaptcha'); if (rc) rc.value = '';
                    showAuthError(res.msg || '注册失败');
                }
            })
            .catch(function() {
                btn.disabled = false;
                btn.textContent = '注 册';
                showAuthError('网络错误，请重试');
            });
        return false;
    }

    function userLogout() {
        var data = new FormData();
        data.append('action', 'logout'); data.append('csrf_token', window.__userCsrfToken || '');
        fetch('api/user_api.php', { method: 'POST', body: data })
            .then(function() { location.reload(); })
            .catch(function() { location.reload(); });
    }

    // ESC 关闭
    document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape') closeAuthCard();
    });
    </script>

