    <!-- PJAX 初始化 -->
    <script>
    (function(){
        if (typeof $ === 'undefined' || !$.fn.pjax) return;

        // ===== 资源管理 =====
        var _loadedCSS = {};
        var _loadedJS = {};
        var _currentPageJS = [];  // 当前页面额外 JS（用于 PJAX 后重新执行）

        function recordExistingResources() {
            document.querySelectorAll('link[rel="stylesheet"]').forEach(function(link) {
                var href = link.getAttribute('href');
                if (href) _loadedCSS[href] = true;
            });
            document.querySelectorAll('script[src]').forEach(function(script) {
                var src = script.getAttribute('src');
                if (src) _loadedJS[src] = true;
            });
        }
        recordExistingResources();

        // 判断是否为公共 CSS
        function isCommonCSS(href) {
            return /common\.css|head\.css|iconfont|font-awesome|toastr\.css|animate\.min|Noto|css2/.test(href);
        }

        // 判断是否为公共 JS
        // 注意：moment-interaction.js 是页面专属脚本（index/list/loveImg 用），
        // 不能列为公共 JS。否则从 chat/message 等不含它的页面 PJAX 进入 loveImg 时，
        // 它不会被加载，导致 toggleLike/openMomentPopup 等函数缺失、点赞评论点击无效。
        function isCommonJS(src) {
            return /jquery|pjax|iconfont|spotlight|funlazy|toastr\.js|head\.js|huaban|app\.js|app-icons\.js|common\.js|api\.js/.test(src);
        }

        // 动态加载 CSS
        function loadCSS(href) {
            if (!href || _loadedCSS[href]) return;
            _loadedCSS[href] = true;
            var link = document.createElement('link');
            link.rel = 'stylesheet';
            link.href = href;
            document.head.appendChild(link);
        }

        // 动态加载 JS
        function loadJS(src) {
            if (!src || _loadedJS[src]) return;
            _loadedJS[src] = true;
            var script = document.createElement('script');
            script.src = src;
            document.body.appendChild(script);
        }

        // ===== PJAX 核心逻辑 =====
        var container = '#pjax-container';

        $(document).pjax('a[data-pjax], .header-nav a, .mobile-bottom-nav a:not(.mobile-music-btn)', container, {
            fragment: container,
            timeout: 8000,
            scrollTo: false,
            maxCacheLength: 0
        });

        // PJAX 请求前
        $(document).on('pjax:send', function() {
            // 清理旧页面特定 JS
            _currentPageJS.forEach(function(src) {
                var el = document.querySelector('script[src="' + src + '"]');
                if (el) el.remove();
                delete _loadedJS[src];
            });
            _currentPageJS = [];
        });

        // PJAX 成功
        $(document).on('pjax:success', function(event, data, status, xhr, options) {
            handlePageSwitch(data);
        });

        // 浏览器前进后退
        $(document).on('pjax:popstate', function() {
            handlePageSwitch();
        });

        // PJAX 失败
        $(document).on('pjax:error', function(event, xhr, textStatus, error, options) {
            if (options.url) {
                window.location.href = options.url;
            }
        });

        // ===== 底部导航胶囊位置统一管理 =====
        // 所有 active 切换 + 胶囊移动统一走这个入口，避免与 PJAX 竞态导致胶囊错位
        function updateMobileNavCapsule() {
            var nav = document.getElementById('mobileBottomNav');
            var capsule = document.getElementById('auroraCapsule');
            if (!nav || !capsule) return;
            // 以当前 URL 精确更新 active 类（确保不会有两个 active 并存）
            var url = window.location.pathname;
            var page = url.substring(url.lastIndexOf('/') + 1) || 'index.php';
            nav.querySelectorAll('.mobile-nav-item:not(.mobile-music-btn)').forEach(function (a) {
                var href = a.getAttribute('href') || '';
                a.classList.toggle('active', href === page);
            });
            // 移动胶囊到真正 active 的项
            var activeItem = nav.querySelector('.mobile-nav-item.active');
            if (activeItem) {
                var navRect = nav.getBoundingClientRect();
                var itemRect = activeItem.getBoundingClientRect();
                capsule.style.left = (itemRect.left - navRect.left) + 'px';
                capsule.style.width = itemRect.width + 'px';
            }
        }

        // ===== 页面切换处理 =====
        function handlePageSwitch(html) {
            var url = window.location.pathname;
            var page = url.substring(url.lastIndexOf('/') + 1) || 'index.php';

            // 更新顶部导航 active 状态
            document.querySelectorAll('.header-nav .nav-bubble').forEach(function(a) {
                var href = a.getAttribute('href') || '';
                a.classList.toggle('active', href === page);
            });

            // 更新底部导航 active + 胶囊位置（统一入口）
            updateMobileNavCapsule();

            // 如果有 HTML 数据，提取并加载额外资源
            if (html && typeof html === 'string') {
                var tmp = document.createElement('div');
                tmp.innerHTML = html;

                // 更新标题
                var titleEl = tmp.querySelector('title');
                if (titleEl) document.title = titleEl.textContent;

                // 加载额外 CSS
                tmp.querySelectorAll('link[rel="stylesheet"]').forEach(function(link) {
                    var href = link.getAttribute('href') || '';
                    if (!isCommonCSS(href)) {
                        loadCSS(href);
                    }
                });

                // 收集额外 JS（排除公共 JS）
                var extraScripts = [];
                tmp.querySelectorAll('script[src]').forEach(function(script) {
                    var src = script.getAttribute('src') || '';
                    if (!isCommonJS(src)) {
                        extraScripts.push(src);
                    }
                });

                // 按顺序加载额外 JS
                _currentPageJS = extraScripts.slice();
                function loadNext() {
                    if (extraScripts.length === 0) {
                        // 所有额外 JS 加载完毕，触发 PJAX 就绪事件
                        // 让依赖 DOMContentLoaded 的代码也能执行
                        document.dispatchEvent(new CustomEvent('pjax:ready'));
                        // 额外 JS 加载可能导致布局抖动，再次对齐胶囊位置
                        updateMobileNavCapsule();
                        return;
                    }
                    var src = extraScripts.shift();
                    // 移除旧的同 src script（确保重新执行）
                    var old = document.querySelector('script[src="' + src + '"]');
                    if (old) old.remove();
                    delete _loadedJS[src];
                    var s = document.createElement('script');
                    s.src = src;
                    s.onload = loadNext;
                    s.onerror = loadNext;
                    document.body.appendChild(s);
                    _loadedJS[src] = true;
                }
                loadNext();

                // 提取并执行 #pjax-container 内的 inline script（jQuery html() 已自动执行，此处无需额外处理）
            }

            // 滚动到内容区域
            if (page !== 'index.php') {
                // 先瞬间回到顶部，再模拟人工滑动下来
                window.scrollTo(0, 0);
                setTimeout(function() { _humanScrollToContent(); }, 80);
            } else {
                // 首页：回顶部
                window.scrollTo(0, 0);
            }
        }

        // 模拟人工缓慢滑动到内容区
        function _humanScrollToContent() {
            var dashedLine = document.querySelector('.dashed-line');
            var pjaxContainer = document.getElementById('pjax-container');
            if (!pjaxContainer) return;

            // 顶部悬浮栏高度偏移
            var headerBar = document.querySelector('.header-bar');
            var headerH = headerBar ? headerBar.offsetHeight : 60;

            // 目标：虚线刚好滚出视口顶部，内容区从悬浮栏下方开始可见
            var targetTop;
            if (dashedLine) {
                targetTop = window.scrollY + dashedLine.getBoundingClientRect().bottom - headerH + 15;
            } else {
                targetTop = window.scrollY + pjaxContainer.getBoundingClientRect().top - headerH - 10;
            }

            var startTop = window.scrollY;
            var distance = targetTop - startTop;
            if (distance <= 0) return;

            // 模拟人工滑动：缓入→匀速→缓出
            var duration = Math.min(Math.max(distance * 1.2, 600), 1500);
            var startTime = null;

            function easeInOutCubic(t) {
                return t < 0.5
                    ? 4 * t * t * t
                    : 1 - Math.pow(-2 * t + 2, 3) / 2;
            }

            function step(timestamp) {
                if (!startTime) startTime = timestamp;
                var elapsed = timestamp - startTime;
                var progress = Math.min(elapsed / duration, 1);
                var eased = easeInOutCubic(progress);
                window.scrollTo(0, startTop + distance * eased);
                if (progress < 1) {
                    requestAnimationFrame(step);
                }
            }

            requestAnimationFrame(step);
        }

        window._pjaxInit = handlePageSwitch;

        // 非首页首次加载时：回顶部再滑动下来
        // 首页首次加载：回顶部再下滑提示
        (function() {
            var url = window.location.pathname;
            var page = url.substring(url.lastIndexOf('/') + 1) || 'index.php';
            if (page !== 'index.php') {
                window.scrollTo(0, 0);
                setTimeout(_humanScrollToContent, 300);
            } else {
                window.scrollTo(0, 0);
            }
        })();
    })();
    </script>

    <!-- 全局加载器控制 -->
    <script src="static/js/navigation-loader.js?v=20261031-2"></script>

    <!-- 访问统计追踪 -->
    <script>
    (function(){
        if (location.pathname.indexOf('/admin/') !== -1) return;
        var data = {
            page_url: location.href,
            page_title: document.title || '',
            referer: document.referrer || '',
            device_type: /Mobi|Android/i.test(navigator.userAgent) ? (/Tablet|iPad/i.test(navigator.userAgent) ? 'tablet' : 'mobile') : 'pc'
        };
        var blob = new Blob([JSON.stringify(data)], {type: 'application/json'});
        if (navigator.sendBeacon) {
            navigator.sendBeacon('api/visit_log.php', blob);
        } else {
            fetch('api/visit_log.php', {method:'POST',body:blob,keepalive:true}).catch(function(){});
        }

        // 触发统计上报（后端 5 分钟限频，fire-and-forget，不影响前端）
        if (navigator.sendBeacon) {
            navigator.sendBeacon('api/stats_report.php', new Blob(['1'], {type: 'text/plain'}));
        } else {
            fetch('api/stats_report.php', {method:'POST',body:'1',keepalive:true}).catch(function(){});
        }
    })();
    </script>

